import { useEffect, useState } from 'react'
import { useParams, useNavigate, useSearchParams } from 'react-router-dom'
import { motion, AnimatePresence } from 'framer-motion'
import { ArrowLeft, Phone, MessageCircle, Star, MapPinned, MoreVertical, Receipt, Store, Map, CheckCircle2, ShoppingBag, HeartHandshake } from 'lucide-react'
import { useOrderDetail, useOrderRealtime } from '@/features/orders/hooks/useOrders'
import { useAuthStore } from '@/store'
import { Container } from '@/components/layout/Container'
import { LiveOrderTracker } from '@/features/orders/components/LiveOrderTracker'
import { formatPrice } from '@/utils/formatPrice'
import { formatOrderDate } from '@/utils/formatDate'
import { trackPageView } from '@/lib/analytics'
import { hapticLight, hapticMedium, hapticHeavy } from '@/utils/haptics'
import { savePendingGuestOrder } from '@/lib/auth'
import { usePointsCalculator } from '@/features/points/hooks/usePoints'
import { useContactInfo } from '@/features/config/hooks/useShopConfig'
import { ReviewForm } from '@/features/reviews/components/ReviewForm'

const fadeUpSpring = {
  hidden: { opacity: 0, y: 30, scale: 0.95 },
  visible: { opacity: 1, y: 0, scale: 1, transition: { type: "spring", stiffness: 300, damping: 24 } }
}

const staggerList = {
  hidden: { opacity: 0 },
  visible: { opacity: 1, transition: { staggerChildren: 0.1, delayChildren: 0.2 } }
}

export default function OrderDetailPage() {
  const { id } = useParams<{ id: string }>()
  const [searchParams] = useSearchParams()
  const navigate = useNavigate()
  const { isGuest } = useAuthStore()
  const { calculateEarned } = usePointsCalculator()

  const orderId = parseInt(id || '0')
  const trackingTokenFromUrl = searchParams.get('token')

  const { data: order, isLoading } = useOrderDetail(orderId)
  const { data: contactInfo } = useContactInfo()
  const [showOptions, setShowOptions] = useState(false)
  useOrderRealtime(orderId)

  useEffect(() => {
    trackPageView(`/orders/${orderId}`, 'Order Detail')
    window.scrollTo(0, 0)
  }, [orderId])

  const handleCallShop = () => {
    hapticMedium()
    if (contactInfo?.phone) {
      window.location.href = `tel:${contactInfo.phone}`
    }
  }

  const handleChatShop = () => {
    hapticHeavy()
    if (contactInfo?.line_id) {
      window.open(`https://line.me/R/ti/p/${contactInfo.line_id}`, '_blank')
    }
  }

  if (isLoading) {
    return (
      <div className="min-h-screen flex items-center justify-center" style={{ background: 'var(--bg-base)' }}>
        <div
          className="w-14 h-14 rounded-full border-4 animate-spin"
          style={{ borderColor: 'var(--border-soft)', borderTopColor: 'var(--brand)' }}
        />
      </div>
    )
  }

  if (!order) {
    return (
      <div className="min-h-screen safe-area-pt flex flex-col items-center justify-center" style={{ background: 'var(--bg-base)' }}>
        <motion.div initial={{ opacity: 0, scale: 0.8 }} animate={{ opacity: 1, scale: 1 }} className="text-center p-8">
          <div
            className="w-24 h-24 rounded-[32px] flex items-center justify-center mx-auto mb-6"
            style={{ background: 'var(--bg-card)', border: '1px solid var(--border-soft)' }}
          >
            <Receipt className="w-10 h-10 text-gray-500" />
          </div>
          <h2 className="font-black text-white text-2xl mb-2">ไม่พบออเดอร์</h2>
          <p className="text-sm mb-8 max-w-xs mx-auto leading-relaxed" style={{ color: 'var(--text-secondary)' }}>
            ออเดอร์นี้อาจถูกยกเลิกแล้ว หรือหมายเลขออเดอร์ไม่ถูกต้อง
          </p>
          <motion.button
            whileTap={{ scale: 0.96 }}
            onClick={() => { hapticLight(); navigate('/orders') }}
            className="text-white px-8 py-3.5 rounded-full font-black text-sm cursor-pointer"
            style={{ background: 'linear-gradient(135deg, #FF5E00, #FF3A00)', boxShadow: '0 8px 20px rgba(255,58,0,0.40)' }}
          >
            กลับไปหน้าออเดอร์
          </motion.button>
        </motion.div>
      </div>
    )
  }

  const pointsMissed = calculateEarned(order.totalPrice)
  const ticketsMissed = Math.floor(order.totalPrice / 100)
  const effectiveToken = trackingTokenFromUrl || order.trackingToken

  return (
    <div className="min-h-screen bg-[var(--bg-base)] pb-28">
      {/* Ambient glow */}
      <div className="fixed inset-0 pointer-events-none z-0 overflow-hidden">
        <div
          className="absolute -top-24 -right-12 w-[300px] h-[300px] rounded-full animate-glow-pulse"
          style={{ background: 'radial-gradient(circle, rgba(255,94,0,0.18) 0%, transparent 70%)', filter: 'blur(60px)' }}
        />
      </div>

      <Container className="py-4 space-y-6">
        {/* Dynamic Nav */}
        <div className="flex items-center justify-between sticky top-4 z-50">
          <motion.button
            type="button"
            aria-label="ย้อนกลับ"
            whileTap={{ scale: 0.9 }}
            onClick={() => { hapticLight(); navigate(-1); }}
            className="w-11 h-11 rounded-[18px] flex items-center justify-center text-gray-300 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-orange-400 cursor-pointer"
            style={{ background: 'var(--bg-card)', border: '1px solid var(--border-soft)' }}
          >
            <ArrowLeft className="w-5 h-5" aria-hidden="true" />
          </motion.button>
          
          <div className="flex flex-col items-center">
            <motion.span initial={{ opacity: 0, y: -10 }} animate={{ opacity: 1, y: 0 }} className="text-[10px] font-black text-[#FF6B00] tracking-widest uppercase bg-[#FF6B00]/10 px-3 py-1 rounded-full mb-1">
              Order Details
            </motion.span>
            <h1 className="text-lg font-black text-white">#{order.id}</h1>
          </div>

          <motion.button
            type="button"
            aria-label="ตัวเลือกเพิ่มเติม"
            aria-expanded={showOptions}
            aria-haspopup="menu"
            whileTap={{ scale: 0.9 }}
            onClick={() => { hapticLight(); setShowOptions(!showOptions); }}
            className="w-11 h-11 rounded-[18px] flex items-center justify-center text-gray-300 relative focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-orange-400 cursor-pointer"
            style={{ background: 'var(--bg-card)', border: '1px solid var(--border-soft)' }}
          >
            <MoreVertical className="w-5 h-5" aria-hidden="true" />
            
            {/* Context Menu */}
            <AnimatePresence>
               {showOptions && (
                 <motion.div 
                   initial={{ opacity: 0, scale: 0.8, transformOrigin: 'top right' }} 
                   animate={{ opacity: 1, scale: 1 }} 
                   exit={{ opacity: 0, scale: 0.8 }}
                   className="absolute top-14 right-0 w-48 rounded-2xl shadow-2xl p-2 z-50 overflow-hidden"
                   style={{ background: 'var(--bg-card)', border: '1px solid var(--border-soft)', backdropFilter: 'blur(20px)' }}
                 >
                    <div className="text-left">
                       <p className="px-3 py-2 text-[10px] font-black uppercase tracking-wider" style={{ color: 'var(--text-micro)' }}>ความช่วยเหลือ</p>
                       <button onClick={handleCallShop} className="w-full flex items-center gap-3 px-3 py-2.5 hover:bg-white/5 rounded-xl transition-colors text-sm font-bold text-gray-300 cursor-pointer">
                          <Phone className="w-4 h-4 text-blue-400" /> โทรติดต่อร้าน
                       </button>
                       <button onClick={handleChatShop} className="w-full flex items-center gap-3 px-3 py-2.5 hover:bg-white/5 rounded-xl transition-colors text-sm font-bold text-gray-300 cursor-pointer">
                          <MessageCircle className="w-4 h-4 text-green-400" /> แชท LINE ร้าน
                       </button>
                    </div>
                 </motion.div>
               )}
            </AnimatePresence>
          </motion.button>
        </div>

        <motion.div variants={staggerList} initial="hidden" animate="visible" className="space-y-5">
          
          {/* Status Tracker */}
          <motion.div variants={fadeUpSpring}>
            <LiveOrderTracker
              orderId={order.id}
              initialStatus={order.status}
              estimatedReadyTime={order.estimatedReadyTime}
            />
          </motion.div>

          {/* Guest Gamification Notice */}
          <AnimatePresence>
          {isGuest && pointsMissed > 0 && (
            <motion.div
              variants={fadeUpSpring}
              initial="hidden" animate="visible" exit="hidden"
              className="relative rounded-3xl overflow-hidden group border border-white/10"
              style={{
                background: 'linear-gradient(135deg, #0D0D0F 0%, #17171C 100%)',
                boxShadow: '0 20px 40px -12px rgba(0,0,0,0.6)',
              }}
            >
              <div className="p-6 relative z-10">
                <div className="flex items-start gap-4 mb-5">
                  <motion.div animate={{ rotate: [0, -10, 10, -10, 0] }} transition={{ duration: 2.5, repeat: Infinity, ease: "easeInOut" }} className="w-14 h-14 rounded-2xl flex items-center justify-center flex-shrink-0 text-3xl shadow-lg border border-white/10" style={{ background: 'rgba(255,255,255,0.06)' }}>
                    🎁
                  </motion.div>
                  <div className="pt-1">
                    <h3 className="font-black text-white text-lg leading-tight mb-1">สะสมพอยต์ก่อนหายไป!</h3>
                    <p className="text-xs leading-relaxed font-medium" style={{ color: 'var(--text-secondary)' }}>คุณพลาดพอยต์ไปแล้ว {pointsMissed} แต้ม ผูก LINE ตอนนี้เพื่อรับพอยต์ย้อนหลังและลุ้นหวยฟรี</p>
                  </div>
                </div>

                <div className="grid grid-cols-3 gap-3 mb-5">
                  <div className="rounded-2xl p-3.5 flex flex-col items-center justify-center border border-white/10" style={{ background: 'var(--bg-surface)' }}>
                    <p className="text-2xl font-black text-amber-400 drop-shadow-md">{pointsMissed}</p>
                    <p className="text-[10px] font-bold mt-1 uppercase tracking-wider" style={{ color: 'var(--text-micro)' }}>Points</p>
                  </div>
                  <div className="rounded-2xl p-3.5 flex flex-col items-center justify-center border border-white/10" style={{ background: 'var(--bg-surface)' }}>
                    <p className="text-2xl font-black text-emerald-400 drop-shadow-md">{ticketsMissed}</p>
                    <p className="text-[10px] font-bold mt-1 uppercase tracking-wider" style={{ color: 'var(--text-micro)' }}>Tickets</p>
                  </div>
                  <div className="rounded-2xl p-3.5 flex flex-col items-center justify-center border border-white/10" style={{ background: 'var(--bg-surface)' }}>
                    <p className="text-2xl font-black text-blue-400 drop-shadow-md">{Math.round(pointsMissed / 10)}</p>
                    <p className="text-[10px] font-bold mt-1 uppercase tracking-wider" style={{ color: 'var(--text-micro)' }}>Baht</p>
                  </div>
                </div>

                <motion.button
                  whileHover={{ scale: 1.02 }} whileTap={{ scale: 0.96 }}
                  onClick={async () => {
                    hapticHeavy();
                    try {
                      if (effectiveToken) savePendingGuestOrder(order.id, effectiveToken)
                      const { loginWithLine } = await import('@/lib/auth')
                      await loginWithLine()
                    } catch (error) {
                      const { useUIStore } = await import('@/store')
                      useUIStore.getState().addToast({ type: 'error', title: 'Login Failed', message: error instanceof Error ? error.message : 'Please try again.' })
                    }
                  }}
                  className="w-full py-4 rounded-2xl font-black text-white text-sm flex items-center justify-center gap-2.5 relative overflow-hidden cursor-pointer"
                  style={{ background: '#00C300', boxShadow: '0 8px 24px -6px rgba(0, 195, 0, 0.5)' }}
                >
                  <MessageCircle className="w-5 h-5" />
                  Claim via LINE
                </motion.button>
              </div>
            </motion.div>
          )}
          </AnimatePresence>

          {/* Delivery & Payment Info */}
          <motion.div variants={fadeUpSpring}>
            <div className="rounded-3xl p-1 shadow-sm border border-white/10" style={{ background: 'var(--bg-card)' }}>
               <div className="rounded-[22px] px-5 py-4 flex items-center justify-between border-b border-white/10" style={{ background: 'var(--bg-surface)' }}>
                  <div className="flex items-center gap-3">
                     <div className="w-10 h-10 rounded-full flex items-center justify-center border border-white/10" style={{ background: 'var(--bg-card)' }}>
                        {order.deliveryMethod === 'workplace' ? <Store className="w-5 h-5 text-blue-400" /> : <Map className="w-5 h-5 text-orange-400" />}
                     </div>
                     <div>
                        <p className="text-xs font-bold uppercase tracking-widest" style={{ color: 'var(--text-muted)' }}>{order.deliveryMethod === 'workplace' ? 'รับที่ออฟฟิศ' : 'ส่งถึงบ้าน'}</p>
                        <p className="font-black text-white">{formatOrderDate(order.createdAt)}</p>
                     </div>
                  </div>
                  <div className="text-right">
                     <div
                       className="inline-flex items-center gap-1.5 px-3 py-1.5 rounded-full text-xs font-black"
                       style={{ background: 'rgba(74,222,128,0.12)', color: '#4ADE80', border: '1px solid rgba(74,222,128,0.20)' }}
                     >
                        <CheckCircle2 className="w-3.5 h-3.5" />
                        ชำระแล้ว
                     </div>
                  </div>
               </div>
               
               <div className="p-5 space-y-4">
                  <div className="flex gap-4 items-start">
                     <div
                       className="w-8 h-8 rounded-full flex items-center justify-center flex-shrink-0 mt-0.5"
                       style={{ background: 'var(--bg-surface)', border: '1px solid var(--border-subtle)' }}
                     >
                        <MapPinned className="w-4 h-4 text-gray-400" />
                     </div>
                     <div>
                        <p className="text-sm font-bold text-white">{order.customerName} <span className="font-medium ml-1" style={{ color: 'var(--text-muted)' }}>({order.phoneNumber || 'ไม่มีเบอร์'})</span></p>
                        <p className="text-sm mt-1 leading-relaxed" style={{ color: 'var(--text-secondary)' }}>{order.address || 'รับที่ร้าน'}</p>
                     </div>
                  </div>

                  {order.specialInstructions && (
                     <div className="flex gap-4 items-start">
                        <div className="w-8 h-8 rounded-full flex items-center justify-center flex-shrink-0 mt-0.5" style={{ background: 'rgba(245,158,11,0.12)' }}>
                           <MessageCircle className="w-4 h-4 text-amber-400" />
                        </div>
                        <div className="rounded-2xl p-3.5 flex-1 border border-amber-500/20" style={{ background: 'rgba(245,158,11,0.06)' }}>
                           <p className="text-xs font-bold text-amber-400 uppercase tracking-widest mb-1">หมายเหตุเพิ่มเติม</p>
                           <p className="text-sm text-amber-200/90 italic font-medium">{order.specialInstructions}</p>
                        </div>
                     </div>
                  )}
               </div>
            </div>
          </motion.div>

          {/* Receipt Style Items List */}
          <motion.div variants={fadeUpSpring}>
             <div className="rounded-3xl overflow-hidden shadow-sm border border-white/10 relative" style={{ background: 'var(--bg-card)' }}>
                <div className="p-6 pt-6 pb-4 border-b border-dashed border-white/10">
                   <h3 className="font-black text-white text-lg flex items-center gap-2 mb-1">
                      <ShoppingBag className="w-5 h-5 text-[#FF6B00]" /> สรุปรายการอาหาร
                   </h3>
                   <p className="text-xs font-bold" style={{ color: 'var(--text-muted)' }}>{order.items.length} รายการในออเดอร์นี้</p>
                </div>

                <div className="p-2">
                   {order.items.map((item, index) => (
                     <div key={index} className="flex gap-4 p-4 hover:bg-white/5 rounded-2xl transition-colors">
                        <div
                          className="w-8 h-8 rounded-xl flex items-center justify-center font-black text-sm flex-shrink-0"
                          style={{ background: 'var(--bg-surface)', color: 'var(--text-secondary)', border: '1px solid var(--border-subtle)' }}
                        >
                           {item.quantity}
                        </div>
                        <div className="flex-1">
                           <div className="flex justify-between items-start mb-1">
                              <h4 className="font-bold text-white text-base leading-tight pr-4">{item.name}</h4>
                              <span className="font-black text-white">{formatPrice(item.subtotal)}</span>
                           </div>
                           
                           {item.options.length > 0 && (
                              <div className="flex flex-wrap gap-1.5 mt-2">
                                 {item.options.map((opt, i) => (
                                    <span key={i} className="text-[10px] font-bold px-2 py-0.5 rounded-lg" style={{ background: 'var(--bg-surface)', color: 'var(--text-muted)', border: '1px solid var(--border-subtle)' }}>
                                       {opt.name}
                                    </span>
                                 ))}
                              </div>
                           )}

                           {item.note && (
                              <div className="mt-2 text-xs px-3 py-2 rounded-xl inline-flex items-center gap-1.5 font-medium" style={{ background: 'var(--bg-surface)', color: 'var(--text-secondary)', border: '1px solid var(--border-subtle)' }}>
                                 {item.note}
                              </div>
                           )}
                        </div>
                     </div>
                   ))}
                </div>

                {/* Subtotals & Totals */}
                <div className="p-6 border-t border-dashed border-white/10 space-y-3" style={{ background: 'var(--bg-surface)' }}>
                   <div className="flex justify-between items-center text-sm font-bold" style={{ color: 'var(--text-secondary)' }}>
                      <span>ยอดรวมค่าอาหาร</span>
                      <span>{formatPrice(order.subtotalPrice)}</span>
                   </div>
                   
                   {order.discountAmount > 0 && (
                     <div
                       className="flex justify-between items-center text-sm font-bold p-2.5 rounded-xl"
                       style={{ background: 'rgba(74,222,128,0.08)', color: '#4ADE80', border: '1px solid rgba(74,222,128,0.18)' }}
                     >
                        <span className="flex items-center gap-2">ส่วนลด</span>
                        <span>-{formatPrice(order.discountAmount)}</span>
                     </div>
                   )}

                   {order.pointsRedeemed > 0 && (
                     <div
                       className="flex justify-between items-center text-sm font-bold p-2.5 rounded-xl"
                       style={{ background: 'rgba(251,191,36,0.08)', color: '#FBBF24', border: '1px solid rgba(251,191,36,0.18)' }}
                     >
                        <span className="flex items-center gap-2"><Star className="w-4 h-4 fill-amber-400 text-amber-400"/> ใช้พอยต์</span>
                        <span>-{formatPrice(order.pointsRedeemed / 10)}</span>
                     </div>
                   )}

                   <div className="pt-4 mt-2 border-t border-white/10 flex justify-between items-end">
                      <div>
                         <p className="text-xs font-black uppercase tracking-widest mb-1" style={{ color: 'var(--text-micro)' }}>ยอดสุทธิ</p>
                         <p className="text-xs font-medium" style={{ color: 'var(--text-muted)' }}>ชำระผ่าน {order.paymentMethod === 'promptpay' ? 'QR Code' : 'เงินสด'}</p>
                      </div>
                      <span className="text-3xl font-black text-gradient-fire tracking-tight num-display">{formatPrice(order.totalPrice)}</span>
                   </div>
                </div>
             </div>
          </motion.div>

          {/* Cancel Action */}
          {(order.status === 'placed' || order.status === 'pending') && (
            <motion.button
               variants={fadeUpSpring}
               whileHover={{ scale: 1.02 }} whileTap={{ scale: 0.98 }}
               onClick={async () => {
                 hapticMedium()
                 if (window.confirm('คุณแน่ใจหรือไม่ว่าต้องการยกเลิกออเดอร์นี้?')) {
                   const { updateOrderStatus } = await import('@/features/orders/hooks/useOrders')
                   try {
                     await updateOrderStatus(order.id, 'cancelled')
                     alert('ยกเลิกออเดอร์สำเร็จ')
                   } catch {
                     alert('ไม่สามารถยกเลิกได้ กรุณาติดต่อร้านค้า')
                   }
                 }
               }}
               className="w-full py-4 font-bold text-sm rounded-2xl transition-all flex items-center justify-center gap-2 cursor-pointer hover:opacity-80"
               style={{ background: 'rgba(239,68,68,0.07)', color: '#F87171', border: '1px solid rgba(239,68,68,0.18)' }}
             >
               ยกเลิกออเดอร์นี้
             </motion.button>
          )}

          {/* Review Section */}
          <AnimatePresence>
            {order.status === 'delivered' && (
              <motion.div variants={fadeUpSpring} initial="hidden" animate="visible">
                <div
                  className="rounded-[28px] overflow-hidden"
                  style={{ background: 'var(--bg-card)', border: '1px solid rgba(99,102,241,0.20)', boxShadow: '0 8px 28px rgba(99,102,241,0.14)' }}
                >
                  <div
                    className="p-5 flex flex-col items-center text-center"
                    style={{ background: 'linear-gradient(135deg, rgba(99,102,241,0.10), rgba(192,132,252,0.06))', borderBottom: '1px solid rgba(99,102,241,0.12)' }}
                  >
                    <div
                      className="w-14 h-14 rounded-[20px] mx-auto mb-3 flex items-center justify-center"
                      style={{ background: 'linear-gradient(135deg, #6366F1, #8B5CF6)', boxShadow: '0 8px 20px rgba(99,102,241,0.40)' }}
                    >
                      <HeartHandshake className="w-7 h-7 text-white" />
                    </div>
                    <h3 className="text-lg font-black text-white mb-1">อาหารอร่อยไหม?</h3>
                    <p className="text-sm font-medium mb-4" style={{ color: 'var(--text-secondary)' }}>บอกเราหน่อย เพื่อให้เราพัฒนาขึ้นในครั้งถัดไป</p>
                  </div>
                  <div className="p-5">
                    <ReviewForm order={order} />
                  </div>
                </div>
              </motion.div>
            )}
          </AnimatePresence>

        </motion.div>
      </Container>
    </div>
  )
}
